// Responses API: schema under text.format (type, name, schema, strict are siblings)
"text": { "format": {
  "type": "json_schema", "name": "Facts", "strict": true,
  "schema": {
    "type": "object",
    "properties": {
      "party": { "type": "string" },
      "po_number": { "type": ["string", "null"] }
    },
    "required": ["party", "po_number"],
    "additionalProperties": false } } }

// Chat Completions: response_format with a json_schema wrapper
"response_format": { "type": "json_schema",
  "json_schema": { "name": "Facts", "strict": true, "schema": { } } }

// JSON mode: valid JSON only, no schema guarantee
"response_format": { "type": "json_object" }

